      type: 'summary',
      agent: 'city-ledger',
      action: 'compress',
      data: {
        originalType: g.type,
        count: g.count,
        agents: Array.from(g.agents),
        actions: Array.from(g.actions),
        sampleIds: g.sampleIds
      },
      tags: ['compressed']
    }));

